class LRUCache:
    __slots__ = ("_capacity", "_data")

    def __init__(self, capacity):
        self._capacity = capacity
        self._data = {}

    def get(self, key):
        data = self._data
        if key not in data:
            return None
        value = data.pop(key)
        data[key] = value
        return value

    def put(self, key, value):
        data = self._data
        if key in data:
            data.pop(key)
        elif len(data) >= self._capacity:
            data.pop(next(iter(data)))
        data[key] = value

    def __len__(self):
        return len(self._data)
